PROGRAM CoilEcho
VAR_INPUT Send AT %I0.0 : BOOL; END_VAR
VAR_OUTPUT Written AT %Q0.0 : BOOL; Echo AT %Q0.1 : BOOL; Failed AT %Q0.2 : BOOL; END_VAR
VAR Wr : MB_WRITE_COIL; Rd : MB_READ_COIL; END_VAR
Wr(EN := Send, PROTO := 1, SLAVE_ID := 1, ADDR := 4, COUNT := 1, VALUE := TRUE, HOST := '127.0.0.1', PORT := 502);
Written := Wr.DONE;
Rd(EN := Wr.DONE, PROTO := 1, SLAVE_ID := 1, ADDR := 4, COUNT := 1, HOST := '127.0.0.1', PORT := 502);
Echo := Rd.DONE AND Rd.VALUE;
Failed := Wr.ERROR OR Rd.ERROR;
END_PROGRAM

